css:
.cba-sim-container {
    padding: 28px;
    background: #f4f5f7;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #1a2744;
}
.cba-sim-header {
    background: linear-gradient(135deg, #1a2744 0%, #2c3e6b 100%);
    color: #ffffff;
    padding: 36px 32px 28px;
    border-radius: 4px;
    margin-bottom: 24px;
    border-bottom: 4px solid #c9a84c;
}
.cba-sim-header-badge {
    display: inline-block;
    background: rgba(201,168,76,0.2);
    color: #c9a84c;
    font-size: 0.7rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    padding: 4px 12px;
    border-radius: 2px;
    border: 1px solid rgba(201,168,76,0.4);
    margin-bottom: 12px;
}
.cba-sim-header h1 {
    font-size: 1.5rem;
    font-weight: 700;
    margin: 0 0 6px 0;
    letter-spacing: -0.01em;
}
.cba-sim-subtitle {
    font-size: 0.9rem;
    color: rgba(255,255,255,0.7);
    margin: 0;
}
.cba-sim-period-counter {
    text-align: center;
    font-size: 0.85rem;
    color: #5a6a7e;
    margin-bottom: 20px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.08em;
}
.cba-sim-period-counter span {
    margin: 0 3px;
}
.cba-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
    margin-bottom: 24px;
}
.cba-sim-kpi-card {
    background: #ffffff;
    border: 1px solid #dde1e7;
    border-radius: 4px;
    padding: 20px 16px;
    text-align: center;
    border-top: 3px solid #1a2744;
}
.cba-sim-kpi-label {
    color: #5a6a7e;
    font-size: 0.68rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin-bottom: 8px;
    font-weight: 600;
}
.cba-sim-kpi-value {
    font-size: 1.9rem;
    font-weight: 700;
    color: #1a2744;
}
.cba-sim-briefing {
    background: #ffffff;
    border: 1px solid #dde1e7;
    border-radius: 4px;
    padding: 28px;
    margin-bottom: 24px;
    border-left: 4px solid #c9a84c;
}
.cba-sim-briefing-tag {
    display: inline-block;
    background: #1a2744;
    color: #ffffff;
    font-size: 0.65rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    padding: 3px 10px;
    border-radius: 2px;
    margin-bottom: 12px;
}
.cba-sim-briefing h3 {
    font-size: 1.15rem;
    font-weight: 700;
    color: #1a2744;
    margin: 0 0 10px 0;
}
.cba-sim-briefing p {
    font-size: 0.88rem;
    color: #3a4a5e;
    line-height: 1.6;
    margin: 0 0 16px 0;
}
.cba-sim-briefing-data {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 12px;
}
.cba-sim-data-item {
    background: #f8f9fb;
    padding: 12px 14px;
    border-radius: 3px;
    border: 1px solid #eceef2;
}
.cba-sim-data-label {
    display: block;
    font-size: 0.65rem;
    color: #5a6a7e;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    margin-bottom: 4px;
    font-weight: 600;
}
.cba-sim-data-value {
    display: block;
    font-size: 1rem;
    font-weight: 700;
    color: #1a2744;
}
.cba-sim-controls {
    background: #ffffff;
    border: 1px solid #dde1e7;
    border-radius: 4px;
    padding: 28px;
    margin-bottom: 24px;
}
.cba-sim-controls h3 {
    font-size: 1rem;
    font-weight: 700;
    color: #1a2744;
    margin: 0 0 20px 0;
    padding-bottom: 12px;
    border-bottom: 1px solid #eceef2;
}
.cba-sim-controls-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 20px;
    margin-bottom: 24px;
}
.cba-sim-control-group label {
    display: block;
    font-size: 0.75rem;
    font-weight: 600;
    color: #3a4a5e;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    margin-bottom: 6px;
}
.cba-sim-controls input[type="number"] {
    background: #f8f9fb;
    border: 1px solid #cdd3dc;
    color: #1a2744;
    border-radius: 3px;
    padding: 10px 14px;
    width: 100%;
    font-size: 0.95rem;
    font-weight: 600;
    transition: border-color 0.2s ease;
}
.cba-sim-controls input[type="number"]:focus {
    border-color: #1a2744;
    outline: none;
    box-shadow: 0 0 0 2px rgba(26,39,68,0.12);
}
.cba-sim-controls select {
    background: #f8f9fb;
    border: 1px solid #cdd3dc;
    color: #1a2744;
    border-radius: 3px;
    padding: 10px 14px;
    width: 100%;
    font-size: 0.88rem;
    font-weight: 500;
    cursor: pointer;
    transition: border-color 0.2s ease;
}
.cba-sim-controls select:focus {
    border-color: #1a2744;
    outline: none;
    box-shadow: 0 0 0 2px rgba(26,39,68,0.12);
}
.cba-sim-controls select option {
    background: #ffffff;
    color: #1a2744;
}
.cba-sim-btn-row {
    display: flex;
    gap: 12px;
    align-items: center;
}
.cba-sim-submit-btn {
    background: #1a2744;
    border: none;
    color: #ffffff;
    padding: 12px 32px;
    font-size: 0.9rem;
    font-weight: 600;
    border-radius: 3px;
    cursor: pointer;
    transition: background 0.2s ease;
}
.cba-sim-submit-btn:hover {
    background: #2c3e6b;
}
.cba-sim-history {
    background: #ffffff;
    border: 1px solid #dde1e7;
    border-radius: 4px;
    padding: 20px;
    margin-bottom: 24px;
    overflow-x: auto;
}
.cba-sim-history table {
    font-size: 0.82rem;
    margin: 0;
}
.cba-sim-history th {
    background: #1a2744;
    color: #ffffff;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    font-weight: 600;
    padding: 10px 12px;
    border: none;
}
.cba-sim-history td {
    padding: 8px 12px;
    vertical-align: middle;
    color: #3a4a5e;
    border-color: #eceef2;
}
.cba-sim-chart-section {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 16px;
    margin-bottom: 24px;
}
.cba-sim-chart-box {
    background: #ffffff;
    border: 1px solid #dde1e7;
    border-radius: 4px;
    padding: 20px;
    min-height: 280px;
}
@media (max-width: 768px) {
    .cba-sim-kpi-grid {
        grid-template-columns: repeat(2, 1fr);
    }
    .cba-sim-controls-grid {
        grid-template-columns: 1fr;
    }
    .cba-sim-briefing-data {
        grid-template-columns: 1fr;
    }
    .cba-sim-chart-section {
        grid-template-columns: 1fr;
    }
    .cba-sim-header h1 {
        font-size: 1.2rem;
    }
}

