        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var en = (this._lang() === 'en' && this.EN && this.EN[idx]) ? this.EN[idx] : null;
            var t = (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };

            var titleEl = document.getElementById('projectTitle');
            if (titleEl) titleEl.textContent = en ? en.title : round.title;

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.textContent = en ? en.description : round.description;

            var costEl = document.getElementById('baseCostDisplay');
            if (costEl) costEl.textContent = '$' + round.baseCost.toLocaleString() + ' ' + t('unit_cost');

            var benEl = document.getElementById('baseBenefitDisplay');
            if (benEl) benEl.textContent = '$' + round.annualBenefit.toLocaleString() + ' ' + t('unit_benefit');

            var horEl = document.getElementById('horizonDisplay');
            if (horEl) horEl.textContent = round.horizon + ' ' + t('unit_years');

            var secEl = document.getElementById('sectorDisplay');
            if (secEl) secEl.textContent = en ? en.sector : round.sector;
        }
